'     local found\n        for _, fname in ipairs(GUARD.KEY_FILES) do\n            pcall(function()\n                if not found and isfile and readfile and isfile(fname) then\n                    local s = readfile(fname)\n                    if type(s) == "string" and #trim(s) >= 4 then found = trim(s) end\n                end\n            end)\n            if found then break end\n        end\n        return found\n    end\n\n    local function notify(msg)\n        -- 1) print luon hoat dong tren moi executor\n        pcall(function() print("[Nexus Hub] " .. tostring(msg)) end)\n        -- 2) NexusLib neu co (khong dung notify Roblox)\n        pcall(function()\n            local slib = _rt.NexusLib\n            if slib and slib.Notify then slib:Notify({ Title = "Nexus Hub", Message = msg, Duration = 6 }) end\n        end)\n    end\n\n    local function deny(reason)\n        notify(reason)\n        pcall(function()\n            if _rt.NexusReport then\n                _rt.NexusReport("Nexus: Thong bao key", tostring(reason) ..\n                    "\\n\\nExecute source truc tiep da bi KHOA. Phai dung loader hwfnew de vao.")\n            end\n        end)\n        LP:Kick("Nexus: " .. tostring(reason))\n    end\n\n    -- ================== B\u{1EA2}O V\u{1EC6} TOKEN HANDOFF CH\u{1ED0}NG BYPASS ==================\n    -- Ch\u{1ED1}ng tr\u{F2} bypass g\u{F5}: getgenv().NexusPremiumVerified = true\n    -- B\u{1EAF}t bu\u{1ED9}c ph\u{1EA3}i c\u{F3} Server Nonce h\u{1EE3}p l\u{1EC7} t\u{1EEB} Loader v\u{1EEB}a g\u{1EED}i sang v\u{E0} ti\u{EA}u th\u{1EE5} ngay (One-time token).\n    local serverNonce = _rt.NexusGuardNonce\n    _rt.NexusGuardNonce = nil -- Ti\u{EA}u th\u{1EE5} ngay l\u{1EAD}p t\u{1EE9}c token d\u{F9}ng 1 l\u{1EA7}n\n\n    local handoffTier = string.upper(tostring(_rt.NexusVerifiedTier or ""))\n    local isValidHandoff = false\n\n    if type(serverNonce) == "string" and #serverNonce >= 8 and handoffTier == "PREMIUM" then\n        isValidHandoff = true\n    elseif _rt.NexusPremiumVerified == true and type(_rt.Key) == "string" and #_rt.Key >= 6 and handoffTier == "PREMIUM" then\n        isValidHandoff = true\n    end\n\n    -- X\u{F3}a to\u{E0}n b\u{1ED9} c\u{1EDD} runtime \u{111}\u{1EC3} kh\u{F4}ng b\u{1ECB} t\u{E1}i s\u{1EED} d\u{1EE5}ng\n    _rt.NexusPremiumVerified = nil\n    _rt.NexusFreemiumVerified = nil\n    _rt.NexusMainLoaded = nil\n    _rt.NexusVerifiedTier = nil\n\n    if not isValidHandoff then\n        -- Execute source tr\u{1EF1}c ti\u{1EBF}p ho\u{1EB7}c c\u{1ED1} t\u{EC}nh set c\u{1EDD} gi\u{1EA3} m\u{1EA1}o -> KICK ngay\n        local reason = "Bao mat: Khong the thuc thi Nexus Premium truc tiep. Phai qua loader chinh thuc!"\n        notify(reason)\n        pcall(function()\n            if _rt.NexusReport then\n                _rt.NexusReport("Nexus Security", reason)\n            end\n        end)\n        LP:Kick("Nexus: " .. reason)\n        while true do task.wait(9999) end\n        return\n    end\n\n    _rt.NexusPremiumVerified = true\nend\n-- ===== END ANTI-BYPASS GUARD =====\n\nlocal runtimeEnv = (getgenv and getgenv()) or _G\n\n-- ===== NEXUSLIB LOADER =====\npcall(function() runtimeEnv.NexusStage("tai NexusLib") end)\nlocal NexusLib = runtimeEnv.NexusLib\nif not NexusLib then\n    local LIB_URL = "https://raw.githubusercontent.com/Ngmankhoi/my-hub/main/NexusLib.lua?v=20261011"\n    local source = nil\n    pcall(function()\n        if isfile and readfile and isfile("NexusLib.lua") then\n            local s = readfile("NexusLib.lua")\n            if type(s) == "string" and #s > 5000 and s:find("CreateWindow", 1, true) then source = s end\n        end\n    end)\n    if not source then\n        local reqFn = (syn and syn.request) or http_request or request or (http and http.request) or (fluxus and fluxus.request)\n        if type(reqFn) == "function" then\n            pcall(function()\n                local r = reqFn({ Url = LIB_URL, Method = "GET" })\n                local body = r and (r.Body or r.body)\n                if type(body) == "string" and #body > 5000 then source = body end\n            end)\n        end\n    end\n    if not source then\n        pcall(function() local s = game:HttpGet(LIB_URL); if type(s) == "string" and #s > 5000 then source = s end end)\n    end\n    if not source then\n        pcall(function() local s = game:GetService("HttpService"):GetAsync(LIB_URL); if type(s) == "string" and #s > 5000 then source = s end end)\n    end\n    if not source then\n        local msg = "[Nexus] Could not download NexusLib. This executor lacks HTTP support."\n        pcall(function() print(msg) end)\n        pcall(function() runtimeEnv.NexusReport("Nexus Hub", msg) end)\n        return\n    end\n    if type(loadstring) ~= "function" then\n        pcall(function() runtimeEnv.NexusReport("Nexus: executor not supported", "This executor has no loadstring -> the hub cannot run.\\nUse a different executor.") end)\n        return\n    end\n    local chunk, compileErr = loadstring(source, "@NexusLib.lua")\n    if not chunk then\n        local msg = "[Nexus] NexusLib compile error: " .. tostring(compileErr)\n        pcall(function() print(msg) end)\n        pcall(function() runtimeEnv.NexusReport("Nexus Hub", msg) end)\n        return\n    end\n    local ok, lib = pcall(chunk)\n    if not ok or type(lib) ~= "table" then\n        local msg = "[Nexus] NexusLib runtime error: " .. tostring(lib)\n        pcall(function() print(msg) end)\n        pcall(function() runtimeEnv.NexusReport("Nexus Hub", msg) end)\n        return\n    end\n    NexusLib = lib\n    runtimeEnv.NexusLib = lib\nend\n\nif runtimeEnv.MinigameAnchorLock then pcall(function() runtimeEnv.MinigameAnchorLock:Disconnect() end) end\nif runtimeEnv.NexusFrameConnection then runtimeEnv.NexusFrameConnection:Disconnect() runtimeEnv.NexusFrameConnection = nil end\nif runtimeEnv.NexusBossFightThread then task.cancel(runtimeEnv.NexusBossFightThread) runtimeEnv.NexusBossFightThread = nil end\nif runtimeEnv.NexusFightEnzoThread then task.cancel(runtimeEnv.NexusFightEnzoThread) runtimeEnv.NexusFightEnzoThread = nil end\nif runtimeEnv.NexusRhyLoop then pcall(function() runtimeEnv.NexusRhyLoop:Disconnect() end) runtimeEnv.NexusRhyLoop = nil end\nif runtimeEnv.AntiAFKConnection then pcall(function() runtimeEnv.AntiAFKConnection:Disconnect() end) runtimeEnv.AntiAFKConnection = nil end\nif runtimeEnv.NexusSpaceGuardConnection then pcall(function() runtimeEnv.NexusSpaceGuardConnection:Disconnect() end) runtimeEnv.NexusSpaceGuardConnection = nil end\nif runtimeEnv.NexusSelectableGuardConnection then pcall(function() runtimeEnv.NexusSelectableGuardConnection:Disconnect() end) runtimeEnv.NexusSelectableGuardConnection = nil end\nif runtimeEnv.NexusNoclipConn then pcall(function() runtimeEnv.NexusNoclipConn:Disconnect() end) runtimeEnv.NexusNoclipConn = nil end\nif runtimeEnv.NexusMinigameConn then pcall(function() runtimeEnv.NexusMinigameConn:Disconnect() end) runtimeEnv.NexusMinigameConn = nil end\nif runtimeEnv.NexusSlamConn then pcall(function() runtimeEnv.NexusSlamConn:Disconnect() end) runtimeEnv.NexusSlamConn = nil end\n\n-- ===== SESSION EPOCH =====\nruntimeEnv.NexusEpoch = (runtimeEnv.NexusEpoch or 0) + 1\nlocal MY_EPOCH = runtimeEnv.NexusEpoch\nlocal function alive() return runtimeEnv.NexusEpoch == MY_EPOCH end\n\n-- ===== SERVICES =====\nlocal Services = {\n    Players = game:GetService("Players"),\n    ReplicatedStorage = game:GetService("ReplicatedStorage"),\n    RunService = game:GetService("RunService"),\n    VirtualUser = game:GetService("VirtualUser"),\n    UserInputService = game:GetService("UserInputService"),\n    Lighting = game:GetService("Lighting"),\n    TweenService = game:GetService("TweenService"),\n    Workspace = game:GetService("Workspace"),\n    Camera = game:GetService("Workspace").CurrentCamera,\n    HttpService = game:GetService("HttpService"),\n    GuiService = game:GetService("GuiService"),\n    TeleportService = game:GetService("TeleportService"),\n    RbxAnalyticsService = game:GetService("RbxAnalyticsService"),\n}\nlocal Players = Services.Players\nlocal ReplicatedStorage = Services.ReplicatedStorage\nlocal RunService = Services.RunService\nlocal VirtualUser = Services.VirtualUser\nlocal UserInputService = Services.UserInputService\nlocal Lighting = Services.Lighting\nlocal TweenService = Services.TweenService\nlocal Workspace = Services.Workspace\nlocal Camera = Services.Camera\n\nlocal LocalPlayer = Players.LocalPlayer\n\n-- ===== GAME DATA =====\nruntimeEnv.NexusStage("waiting for game data (Events/MainGui/Info/Data)")\nlocal Events = runtimeEnv.NexusNeedChild(ReplicatedStorage, "Events", 30)\nif not Events then return end\nlocal StartBossFight = Events:FindFirstChild("StartBossFight")\nlocal BossPhase2Action = Events:FindFirstChild("BossPhase2Action")\nlocal MainGui = runtimeEnv.NexusNeedChild(LocalPlayer:WaitForChild("PlayerGui", 30), "MainGui", 30)\nif not MainGui then return end\nlocal Info = runtimeEnv.NexusNeedChild(ReplicatedStorage, "Info", 30)\nif not Info then return end\nlocal Data = runtimeEnv.NexusNeedChild(ReplicatedStorage, "Data", 30)\nif not Data then return end\n\nfor _, v in pairs(LocalPlayer:WaitForChild("PlayerGui"):GetChildren()) do\n    if v.Name:find("MobileToggle") then v:Destroy() end\nend\npcall(function()\n    for _, v in pairs(game:GetService("CoreGui"):GetChildren()) do\n        if v.Name:find("MobileToggle") then v:Destroy() end\n    end\nend)\n\nlocal CODES = {\n    "BigUPD", "23MVisits", "24MVisits", "25MVisits", "26MVisits",\n    "42KLikes", "43KLikes", "44KLikes", "45KLikes", "UIBUG",\n    "33MVisits", "31MVisits", "32MVisits"\n}\n\n-- ============================================================\n-- ===== STATE TABLE =====\n-- ============================================================\nlocal NexusState = {\n    Fishing = {\n        Flags = {\n            MainFarm = true,\n            AutoCast = false,\n            AutoSkill = false,\n            SelectedSkills = { "Z", "X", "C", "V" },\n            SkillMode = "Spam",\n            SkillSequence = "Z,X,C,V",\n            SkillDelay = 0.3,\n            AutoFarmBoss = false,\n            AutoFarmSecretBoss = false,\n            AnchorLock = false,\n            AntiAFK = false,\n            AutoSkillCheck = false,\n            BossFightMode = "Normal",\n            BossFightThread = nil,\n            AutoFightEnzo = false,\n            AutoFightLongDiaohai = false,\n            AutoLongDiaohai = false,\n            LongDiaohaiFightMode = "Normal",\n            LastCancel = 0,\n            LastFastCancel = 0,\n            LastProgress = 0,\n            LastNotify = ""\n        },\n        BossFarm = {\n            CurrentTarget = nil,\n            CurrentType = nil,\n            CurrentToken = nil,\n            CurrentRunId = 0,\n            HasHooked = false,\n            PendingCancel = false,\n            LastCast = 0,\n            LastCancel = 0,\n            LastFastCancel = 0,\n            LastProgress = 0,\n            LastNotify = ""\n        }\n    },\n    MiscFlags = {\n        FlyMode = false,\n        Noclip = false,\n        InfiniteJump = false,\n        WalkOnWater = false,\n        FullBright = false,\n        AutoSell = false,\n        AutoBuy = false,\n        AutoEquipBait = false,\n        AutoEquipRod = false,\n    },\n    islands = {\n        {name = "Island 1", cframe = CFrame.new(-297, 9, 12), power = 0},\n        {name = "Island 2", cframe = CFrame.new(-1274, 21, -270), power = 17},\n        {name = "Island 3", cframe = CFrame.new(57, 9, 1115), power = 28},\n        {name = "Island 4", cframe = CFrame.new(-1343, 9, 1083), power = 35},\n        {name = "Island 5", cframe = CFrame.new(-12, 9, -1696), power = 45},\n        {name = "Island 6", cframe = CFrame.new(-1184, 20, -1652), power = 55},\n        {name = "Island 7", cframe = CFrame.new(1470, 9, -1685), power = 62},\n        {name = "Island 8", cframe = CFrame.new(1130, 9, 1364), power = 72},\n        {name = "Island 9", cframe = CFrame.new(1459, 8, -248), power = 90},\n        {name = "Island 10", cframe = CFrame.new(3028, 16, -124), power = 100},\n        -- Island 11 (if u have ego and tiger): chi duoc recommend khi co ca rod Ego va Tiger\n        {name = "Island 11", cirstChild("Head")\n            if not head then return end\n            local billboard = head:FindFirstChild("EspBillboard")\n            if billboard then billboard:Destroy() end\n            for i, conn in ipairs(espConnections) do\n                if conn.player == player then\n                    table.remove(espConnections, i)\n                    break\n                end\n            end\n        end\n        \n        local function clearAllEsp()\n            for _, conn in ipairs(espConnections) do\n                pcall(function()\n                    if conn.billboard and conn.billboard.Parent then\n                        conn.billboard:Destroy()\n                    end\n                end)\n            end\n            espConnections = {}\n        end\n        \n        local function updateAllEsp()\n            if not espEnabled then return end\n            clearAllEsp()\n            for _, player in ipairs(Players:GetPlayers()) do\n                if player ~= LocalPlayer then\n                    pcall(function() createEspForPlayer(player) end)\n                end\n            end\n        end\n        \n        local function startEsp()\n            if espEnabled then return end\n            espEnabled = true\n            updateAllEsp()\n            \n            local playerAddedConn = Players.PlayerAdded:Connect(function(player)\n                if espEnabled then\n                    task.wait(0.5)\n                    pcall(function() createEspForPlayer(player) end)\n                end\n            end)\n            table.insert(espConnections, { conn = playerAddedConn })\n            \n            local playerRemovingConn = Players.PlayerRemoving:Connect(function(player)\n                pcall(function() removeEspForPlayer(player) end)\n            end)\n            table.insert(espConnections, { conn = playerRemovingConn })\n            \n            local characterAddedConn = Players.PlayerAdded:Connect(function(player)\n                if espEnabled then\n                    player.CharacterAdded:Connect(function()\n                        task.wait(0.5)\n                        pcall(function() createEspForPlayer(player) end)\n                    end)\n                end\n            end)\n            table.insert(espConnections, { conn = characterAddedConn })\n            \n            espThread = task.spawn(function()\n                while espEnabled do\n                    task.wait(10)\n                    if espEnabled then\n                        pcall(updateAllEsp)\n                    end\n                end\n            end)\n            \n            NexusLib:Notify({ Title = "ESP", Message = "Players ESP enabled!", Duration = 2 })\n        end\n        \n        local function stopEsp()\n            espEnabled = false\n            if espThread then\n                task.cancel(espThread)\n                espThread = nil\n            end\n            clearAllEsp()\n            for _, conn in ipairs(espConnections) do\n                if conn.conn then\n                    pcall(function() conn.conn:Disconnect() end)\n                end\n            end\n            espConnections = {}\n            NexusLib:Notify({ Title = "ESP", Message = "Players ESP disabled!", Duration = 2 })\n        end\n        \n        Cfg.register(EspSection:CreateToggle(Cfg.wrap("Toggle", "Players", {\n            Name = "Players",\n            Default = false,\n            Callback = function(value)\n                if value then\n                    startEsp()\n                else\n                    stopEsp()\n                end\n            end\n        })), "Toggle", "Players", {\n            Name = "Players",\n            Default = false,\n            Callback = function(value)\n                if value then\n                    startEsp()\n                else\n                    stopEsp()\n                end\n            end\n        })\n        \n        -- ===== BOAT ESP =====\n        do\n            local boatEspEnabled = false\n            local boatEspThread = nil\n            local boatEspHighlights = {}\n            local boatFolder = workspace:FindFirstChild("Boat")\n            \n            local function createBoatEsp(boatModel)\n                if not boatModel or typeof(boatModel) ~= "Instance" or not boatModel:IsA("Model") then return end\n                if boatEspHighlights[boatModel] then return end\n                \n                -- Only handle it when the parent is a Folder\n                if not boatModel.Parent or typeof(boatModel.Parent) ~= "Instance" or not boatModel.Parent:IsA("Folder") then return end\n                \n                local attachPart = boatModel:FindFirstChildWhichIsA("BasePart")\n                if not attachPart then\n                    attachPart = boatModel:FindFirstChildWhichIsA("BasePart", true)\n                end\n                if not attachPart then return end\n                \n                local parentName = "Boat"\n                local parent = boatModel.Parent\n                if parent and parent ~= boatFolder then\n                    parentName = parent.Name\n                end\n                \n                local highlight = Instance.new("Highlight")\n                highlight.FillColor = Color3.fromRGB(0, 150, 255)\n                highlight.FillTransparency = 0.5\n                highlight.OutlineColor = Color3.fromRGB(0, 255, 255)\n                highlight.OutlineTransparency = 0.3\n                highlight.Adornee = boatModel\n                highlight.Parent = boatModel\n                \n                local billboard = Instance.new("BillboardGui")\n                billboard.Name = "BoatEspBillboard"\n                billboard.Size = UDim2.new(0, 150, 0, 30)\n                billboard.StudsOffset = Vector3.new(0, 2, 0)\n                billboard.AlwaysOnTop = true\n                billboard.Parent = attachPart\n                \n                local frame = Instance.new("Frame")\n                frame.Size = UDim2.new(1, 0, 1, 0)\n                frame.BackgroundColor3 = Color3.fromRGB(0, 0, 0)\n                frame.BackgroundTransparency = 0.5\n                frame.BorderSizePixel = 0\n                frame.Parent = billboard\n                \n                local corner = Instance.new("UICorner")\n                corner.CornerRadius = UDim.new(0, 4)\n                corner.Parent = frame\n                \n                local label = Instance.new("TextLabel")\n                label.Size = UDim2.new(1, 0, 1, 0)\n                label.BackgroundTransparency = 1\n                label.Font = Enum.Font.GothamBold\n                label.TextSize = 14\n                label.TextColor3 = Color3.fromRGB(0, 0, 255)\n                label.Text = "Boat | " .. parentName\n                label.TextScaled = false\n                label.TextXAlignment = Enum.TextXAlignment.Center\n                label.TextYAlignment = Enum.TextYAlignment.Center\n                label.Parent = frame\n                \n                boatEspHighlights[boatModel] = {\n                    highlight = highlight,\n                    billboard = billboard,\n                    attachPart = attachPart,\n                }\n            end\n            \n            local function removeBoatEsp(boatModel)\n                local data = boatEspHighlights[boatModel]\n                if data then\n                    if data.highlight then data.highlight:Destroy() end\n                    if data.billboard then data.billboard:Destroy() end\n                    boatEspHighlights[boatModel] = nil\n                end\n            end\n            \n            local function clearAllBoatEsp()\n                for model, data in pairs(boatEspHighlights) do\n                    pcall(function()\n                        if data.highlight then data.highlight:Destroy() end\n                        if data.billboard then data.billboard:Destroy() end\n                    end)\n                end\n                boatEspHighlights = {}\n            end\n            \n            local function scanAllBoats()\n                if not boatFolder then return end\n                for _, child in ipairs(boatFolder:GetDescendants()) do\n                    if typeof(child) == "Instance" and child:IsA("Model") and child.Parent and typeof(child.Parent) == "Instance" and child.Parent:IsA("Folder") then\n                        if not boatEspHighlights[child] then\n                            pcall(function() createBoatEsp(child) end)\n                        end\n                    end\n                end\n            end\n            \n            local function startBoatEsp()\n                if boatEspEnabled then return end\n                boatEspEnabled = true\n                scanAllBoats()\n                \n                if boatFolder then\n                    local boatAddedConn = boatFolder.DescendantAdded:Connect(function(desc)\n                        if boatEspEnabled and typeof(desc) == "Instance" and desc:IsA("Model") and desc.Parent and typeof(desc.Parent) == "Instance" and desc.Parent:IsA("Folder") then\n                            task.wait(0.1)\n                            pcall(function()\n                                if not boatEspHighlights[desc] then\n                                    createBoatEsp(desc)\n                                end\n                            end)\n                        end\n                    end)\n                    table.insert(espConnections, { conn = boatAddedConn })\n                end\n                \n                boatEspThread = task.spawn(function()\n                    while boatEspEn