50732,'   local userData = Data:FindFirstChild(tostring(LocalPlayer.UserId))\n            if not userData then return 0 end\n            local names = {"Crystals", "Gems", "Diamonds", "Crystal", "Gem"}\n            for _, name in ipairs(names) do\n                local val = userData:FindFirstChild(name)\n                if typeof(val) == "Instance" and val:IsA("NumberValue") then\n                    return val.Value\n                end\n            end\n            local currency = userData:FindFirstChild("Currency")\n            if currency then\n                for _, name in ipairs(names) do\n                    local val = currency:FindFirstChild(name)\n                    if typeof(val) == "Instance" and val:IsA("NumberValue") then\n                        return val.Value\n                    end\n                end\n            end\n            return 0\n        end\n\n        local bannerOptions = {"Egoless Banner", "Celestial Banner"}\n        local selectedBanner = bannerOptions[1]\n        local amountOptions = {"1", "10"}\n        local selectedAmount = "1"\n\n        local bannerDropdown = Cfg.register(gachaSection:CreateDropdown(Cfg.wrap("Dropdown", "Select Banner", {\n            Name = "Select Banner",\n            Options = bannerOptions,\n            Default = selectedBanner,\n            Callback = function(value) selectedBanner = value end\n        })), "Dropdown", "Select Banner", {\n            Name = "Select Banner",\n            Options = bannerOptions,\n            Default = selectedBanner,\n            Callback = function(value) selectedBanner = value end\n        })\n        local amountDropdown = Cfg.register(gachaSection:CreateDropdown(Cfg.wrap("Dropdown", "Tickets per roll", {\n            Name = "Tickets per roll",\n            Options = amountOptions,\n            Default = selectedAmount,\n            Callback = function(value) selectedAmount = value end\n        })), "Dropdown", "Tickets per roll", {\n            Name = "Tickets