tService(\"Players\")\n    local HttpService = game:GetService(\"HttpService\")\n    local LP = Players.LocalPlayer\n\n    -- Anti-Hook / Anti-Dump check\n    local _raw_loadstring = loadstring\n    local function isHooked(f)\n        if type(f) ~= \"function\" then return false end\n        if ishooked and ishooked(f) then return true end\n        return false\n    end\n    if isHooked(_raw_loadstring) or (loadstring and isHooked(loadstring)) then\n        LP:Kick(\"Nexus Security: loadstring tampering detected.\")\n        while true do task.wait(9999) end\n        return\n    end\n\n    local GUARD = {\n        API_URL = \"https://vgvaxescpirfdkrcamyk.supabase.co/functions/v1/key-system\",\n        PROTOCOL_VERSION = 3,\n        -- Freemium chi doc file FREEMIUM (khong doc file premium de tranh de lan)\n        KEY_FILES = { \"NexusFreemiumKey.txt\" },\n        TIMEOUT = 20,\n        RETRY = 2,\n        -- Doi thanh true neu muon: khong tim thay key thi VAN CHAY (che do offline).\n        OFFLINE_FALLBACK = true,\n    }\n\n    local function getHWID()\n        local candidates = {\n            function() return gethwid and gethwid() end,\n            function() return game:GetService(\"RbxAnalyticsService\"):GetClientId() end,\n        }\n        for _, getter in ipairs(candidates) do\n            local ok, value = pcall(getter)\n            if ok and type(value) == \"string\" and #value >= 8 then\n                return value .. \":\" .. tostring(LP.UserId)\n            end\n        end\n        return string.format(\"player:%d:place:%d\", LP.UserId, game.PlaceId)\n    end\n\n    local _raw_req = (syn and syn.request) or http_request or request or (fluxus and fluxus.request)\n    local function requestAdapter()\n        return _raw_req or (syn and syn.request) or http_request or request or (fluxus and fluxus.request)\n    end\n\n    local function api(action, fields)\n        local payload = fields or {}\n        payload.action = action\n        payload.protocol