= \"\",\n[\"Equip Best Orb\"] = \"\",\n            [\"Teleport to Nameless Octoparasite\"] = \"\",\n            [\"Unlock all fish\"] = \"\",\n            [\"Upgrade Selected Skill\"] = \"\",\n            [\"Craft rod now\"] = \"\",\n            [\"Buy Now\"] = \"\",\n            [\"Buy Selected Rod\"] = \"\",\n            [\"Learn Selected Skills\"] = \"\",\n            [\"Reroll Until Trait\"] = \"\",\n            [\"Craft bait now\"] = \"\",\n            [\"Exchange now\"] = \"\",\n            [\"Claim Daily Rewards\"] = \"\",\n            [\"Check Resources\"] = \"\",\n            [\"Redeem All Codes\"] = \"\",\n            [\"Refresh List\"] = \"\",\n            [\"Delete Job ID\"] = \"Job ID\",\n            [\"Join by Job ID\"] = \"Job ID\",\n            [\"Check Current Players\"] = \"\",\n            [\"Teleport to Player\"] = \"\",\n            [\"Spectate Player\"] = \"\",\n            [\"Teleport To Current Weather\"] = \"\",\n            [\"Teleport to Recommend Island\"] = \"\",\n            [\"Teleport to selected NPC\"] = \"NPC\",\n            [\"Teleport to selected Secret Rod\"] = \"\",\n            [\"TP to Man return handle end\n        local kind = cfgKind(callKind)\n        local entry = ConfigSys.registry[name]\n        if not entry then\n            entry = { kind = kind }\n            ConfigSys.registry[name] = entry\n            table.insert(ConfigSys.ordered, name)\n        end\n        entry.kind = kind\n        -- The original Callback is captured here at registration time (from the\n        -- config table), because NexusLib handles do not expose it.\n        local cb = config and config.Callback or nil\n        if type(handle.Get) == \"function\" then\n            entry.get = function()\n                local ok, v = pcall(handle.Get)\n                return ok and v or nil\n            end\n        end\n        -- NOTE: NexusLib Set() implementations do NOT fire Callback (toggle Set\n        -- calls set(v, false); dropdown/text Set only touch the label). After\n        -- Set we therefore re-fire the captured Callback so the hub state\n        -- (Fishing.Flags, NexusState, ...) actually follows the loaded value.\n        if type(handle.Set) == \"function\" then\n            entry.set = function(v)\n                pcall(handle.Set, handle, v)\n                if cb then\n                    task.spawn(cb, v)\n                end\n            end\n        elseif cb then\n            entry.set = function(v)\n                task.spawn(cb, v)\n            end\n        end\n        return handle\n    end\n\n    function ConfigSys.snapshot()\n        local out = {}\n        for name, entry in pairs(ConfigSys.registry) do\n            if entry.get then\n                local ok, v = pcall(entry.get)\n                if ok and v ~= nil then out[name] = v end\n            end\n        end\n        return out\n    end\n\n    function ConfigSys.apply(data)\n        if type(data) ~= \"table\" then return 0, 0 end\n        local okCount, missCount = 0, 0\n        for name, value in pairs(data) do\n            local entry = ConfigSys.registry[name]\n            if entry and entry.set then\n                local ok = pcall(entry.set, value)\n                if ok then okCount = okCount + 1 else missCount = missCount + 1 end\n            else\n                missCount = missCount + 1\n            end\n        end\n        return okCount, missCount\n    end\n\n    local function encode(data)\n        local HttpService = Services.HttpService\n        local ok, s = pcall(HttpService.JSONEncode, HttpService, data)\n        return ok and s or nil\n    end\n\n    local function decode(s)\n        local HttpService = Services.HttpService\n        local ok, data = pcall(HttpService.JSONDecode, HttpService, s)\n        if ok and type(data) == \"table\" then return data end\n        return nil\n    end\n\n    function ConfigSys.save(slot)\n        local payload = encode({ version = 1, savedAt = os.time(), data = ConfigSys.snapshot() })\n        if not payload then\n            NexusLib:Notify({ Title = \"Config\", Message = \"Encode failed.\", Duration = 3 })\n            return false\n        end\n        if not writefile then\n            NexusLib:Notify({ Title = \"Config\", Message = \"This executor cannot save files.\", Duration = 3 })\n            return false\n        end\n        local ok = pcall(writefile, slot or ConfigSys.FILE, payload)\n        NexusLib:Notify({ Title = \"Config\", Message = ok and \"Saved.\" or \"Save failed.\", Duration = 2 })\n        return ok\n    end\n\n    function ConfigSys.load(slot, silent)\n        if not (isfile and readfile) then\n            if not silent then NexusLib:Notify({ Title = \"Config\", Message = \"This executor cannot read files.\", Duration = 3 }) end\n            return false\n        end\n        local path = slot or ConfigSys.FILE\n        local has = false\n        pcall(function() has = isfile(path) end)\n        if not has then\n            if not silent then NexusLib:Notify({ Title = \"Config\", Message = \"No saved config found.\", Duration = 3 }) end\n            return false\n        end\n        local ok, raw = pcall(readfile, path)\n        if not ok or not raw then\n            if not silent then NexusLib:Notify({ Title = \"Config\", Message = \"Read failed.\", Duration = 3 }) end\n            return false\n        end\n        local wrap = decode(raw)\n        local data = wrap and (wrap.data or wrap) or nil\n        if not data then\n            if not silent then NexusLib:Notify({ Title = \"Config\", Message = \"Config file is corrupt.\", Duration = 3 }) end\n            return false\n        end\n        -- Defer one frame so every tab has finished building its controls.\n        task.defer(function()\n            local okCount, missCount = ConfigSys.apply(data)\n            if not silent then\n                NexusLib:Notify({ Title = \"Config\", Message = \"Loaded \" .. okCount .. \" settings\" .. (missCount > 0 and \" (\" .. missCount .. \" skipped)\" or \"\") .. \".\", Duration = 3 })\n            end\n        end)\n        return true\n    end\n\n    function ConfigSys.exportCode()\n        local payload = encode({ version = 1, savedAt = os.time(), data = ConfigSys.snapshot() })\n        if not payload then return nil end\n        local clip = (syn and syn.write_clipboard) or setclipboard or toclipboard\n        if clip then\n            pcall(clip, payload)\n            NexusLib:Notify({ Title = \"Config\", Message = \"Config code copied to clipboard.\", Duration = 3 })\n        else\n            NexusLib:Notify({ Title = \"Config\", Message = \"Clipboard not supported on this executor.\", Duration = 3 })\n        end\n        return payload\n    end\n\n    -- Import reads the clipboard when the executor exposes it; otherwise it falls\n    -- back to the textbox value typed/pasted by the user.\n    function ConfigSys.importCode(text)\n        local code = text\n        if (not code or code == \"\") and getclipboard then\n            pcall(function() code = getclipboard() end)\n        end\n        if not code or code == \"\" then\n            NexusLib:Notify({ Title = \"Config\", Message = \"Paste a config code first.\", Duration = 3 })\n            return false\n        end\n        local wrap = decode(code)\n        local data = wrap and (wrap.data or wrap) or nil\n        if not data then\n            NexusLib:Notify({ Title = \"Config\", Message = \"Invalid config code.\", Duration = 3 })\n            return false\n        end\n        task.defer(function()\n            local okCount, missCount = ConfigSys.apply(data)\n            NexusLib:Notify({ Title = \"Config\", Message = \"Imported \" .. okCount .. \" settings\" .. (missCount > 0 and \" (\" .. missCount .. \" skipped)\" or \"\") .. \".\", Duration = 3 })\n        end)\n        return true\n    end\n\n    runtimeEnv.NexusConfig = ConfigSys\n    runtimeEnv.NexusCfgWrap = ConfigSys.wrap\n    ConfigSys._saving = false\nend\n\n\nlocal Cfg = runtimeEnv.NexusConfig\n\n-- ===== HOME TAB =====\n-- ============================================================\ndo\n    runtimeEnv.NexusStage(\"dung UI: Session tab\")\n    local HomeTab\n    do\n        runtimeEnv.NexusStage(\"dung UI: Session tab\")\n        local ok, result = pcall(function() return Window:CreateTab(\"Session\") end)\n        if not ok or result == nil then\n            runtimeEnv.NexusStage(\"UI Session tab failed\")\n            runtimeEnv.NexusReport(\"Nexus UI failed\", \"CreateTab Session: \" .. tostring(result))\n            return\n        end\n        HomeTab = result\n    end\n    HomeTab:CreateHeader({\n        Title = \"Session overview\",\n        Subtitle = \"Live instruments for \" .. LocalPlayer.Name\n    })\n    local statRow = HomeTab:CreateStatRow({\n        {Title = \"LEVEL\", Value = \"...\", Color = Color3.fromRGB(190, 158, 103)},\n        {Title = \"BALANCE\", Value = \"...\", Color = Color3.fromRGB(128, 159, 164)},\n        {Title = \"SESSION\", Value = \"00:00:00\", Color = Color3.fromRGB(139, 161, 142)}\n    })\n        -- Add 9 new stats\n    local statRow2 = HomeTab:CreateStatRow({\n        {Title = \"ROD\", Value = \"...\", Color = Color3.fromRGB(255, 215, 0)},\n        {Title = \"CRYSTAL\", Value = \"...\", Color = Color3.fromRGB(100, 200, 255)},\n        {Title = \"ESSENCE\", Value = \"...\", Color = Color3.fromRGB(255, 100, 200)}\n    })\n    local statRow3 = HomeTab:CreateStatRow({\n        {Title = \"BAIT\", Value = \"...\", Color = Color3.fromRGB(150, 255, 150)},\n        {Title = \"FISH CAUGHT\", Value = \"...\", Color = Color3.fromRGB(255, 200, 100)},\n        {Title = \"TICKET\", Value = \"...\", Color = Color3.fromRGB(200, 150, 255)}\n    })\n    local statRow4 = HomeTab:CreateStatRow({\n        {Title = \"TRAIT REROLL\", Value = \"...\", Color = Color3.fromRGB(255, 150, 150)},\n        {Title = \"HEAVIEST FISH\", Value = \"...\", Color = Color3.fromRGB(255, 180, 50)},\n        {Title = \"BASE HP\", Value = \"...\", Color = Color3.fromRGB(255, 100, 100)}\n    })\n    local hwid = \"N/A\"\n    pcall(function() hwid = Services.RbxAnalyticsService:GetClientId() end)\n    HomeTab:CreateFeaturedCard({\n        Tag = \"Nexus\",\n        Title = \"Heavyweight Fishing\",\n        Description = \"Script by: Ngmankhoi,NgdepZaiNhatTG,Ethangcuto\\n\\nHWID: \" .. string.sub(hwid, 1, 15) .. \"...\",\n        ButtonText = \"DISCORD\",\n        Callback = function()\n            NexusLib:Notify({ Title = \"Discord\", Message = \"Link copied to clipboard!\", Duration = 3 })\n            if setclipboard then setclipboard(\"https://discord.gg/QAdVUX2wCH\") end\n        end\n    })\n\n        local scriptStartTime = time()\n        task.spawn(function()\n        -- Cache for every stat row\n        local cachedStat1, cachedStat2, cachedStat3\n        local cachedStat2_1, cachedStat2_2, cachedStat2_3\n        local cachedStat3_1, cachedStat3_2, cachedStat3_3\n        local cachedStat4_1\n        local cachedStat4_2, cachedStat4_3\n        local labelCache = {}\n\n        local function setStat(statFrame, text)\n            if not statFrame then return end\n            local lbl = labelCache[statFrame]\n            if not lbl or not lbl.Parent then\n                for _, child in ipairs(statFrame:GetDescendants()) do\n                    if typeof(child) == \"Instance\" and typeof(child) == \"Instance\" and child:IsA(\"TextLabel\") and child.TextSize >= 18 then\n                        lbl = child\n                        labelCache[statFrame] = child\n                        break\n                    end\n                end\n            end\n            if lbl and lbl.Text ~= text then lbl.Text = text end\n        end\n\n        -- Stats fetch helper\n        local function getHomeStats()\n            local userData = Data:FindFirstChild(tostring(LocalPlayer.UserId))\n            if not userData then return {} end\n            local stats = {}\n            local levelFolder = userData:FindFirstChild(\"Level\")\n            stats.Level = levelFolder and levelFolder:FindFirstChild(\"Level\") and tostring(levelFolder.Level.Value) or \"N/A\"\n            stats.Cash = userData:FindFirstChild(\"Cash\") and tostring(userData.Cash.Value) or \"N/A\"\n            stats.Rod = userData:FindFirstChild(\"FishingRod\") and tostring(userData.FishingRod.Value) or \"N/A\"\n            stats.Crystal = userData:FindFirstChild(\"Crystal\") and tostring(userData.Crystal.Value) or \"N/A\"\n            stats.EssenceOrb = userData:FindFirstChild(\"EssenceOrb\") and tostring(userData.EssenceOrb.Value) or \"N/A\"\n            stats.Bait = userData:FindFirstChild(\"EquippedBait\") and tostring(userData.EquippedBait.Value) or \"N/A\"\n            stats.FishCaught = userData:FindFirstChild(\"FishCaught\") and tostring(userData.FishCaught.Value) or \"N/A\"\n            stats.Ticket = userData:FindFirstChild(\"Ticket\") and tostring(userData.Ticket.Value) or \"N/A\"\n            stats.TraitReroll = userData:FindFirstChild(\"Trait Reroll\") and tostring(userData[\"Trait Reroll\"].Value) or \"N/A\"\n            stats.HeaviestWeight = userData:FindFirstChild(\"HeaviestWeight\") and tostring(userData.HeaviestWeight.Value) or \"N/A\"\n            stats.BaseHP = userData:FindFirstChild(\"BaseHP\") and tostring(userData.BaseHPwrite_clipboardNexusLibMethod\xF3\x03a\x02!\x03b\x02\xC8\x02",
