'         else\n                    if NexusState.autoClaimThread then\n                        task.cancel(NexusState.autoClaimThread)\n                        NexusState.autoClaimThread = nil\n                    end\n                    NexusState.ticketFailCount = 0\n                    NexusLib:Notify({ Title = "Quest", Message = "Auto claim stopped", Duration = 2 })\n                end\n            end\n        })), "Toggle", "Auto Claim Ticket Quest (Fast)", {\n            Name = "Auto Claim Ticket Quest (Fast)",\n            Default = false,\n            Callback = function(value)\n                NexusState.autoClaimRunning = value\n                if value then\n                    if NexusState.autoClaimThread then\n                        task.cancel(NexusState.autoClaimThread)\n                        NexusState.autoClaimThread = nil\n                    end\n                    NexusState.autoClaimThread = task.spawn(function()\n                        while NexusState.autoClaimRunning do\n                            pcall(function()\n                                if not HasActiveQuest() then\n                                    if tick() - (NexusState.ticketLastFire or 0) < 3 then return end\n                                    NexusState.ticketLastFire = tick()\n                                    local selAction = nil\n                                    if selectedQuest == "Easy Quest" then\n                                        selAction = "EasyAcceptQuest"\n                                    else\n                                        selAction = "HardAcceptQuest"\n                                    end\n                                    if ticketGoFire(selAction) and HasActiveQuest() then\n                                        NexusState.ticketFailCount = 0\n                                        NexusLib:Notify({\n                                            Title = "Quest",\n                                            Message = "Claimed " .. selectedQuest,\n                                            Duration = 2\n                                        })\n                                    else\n                                        NexusState.ticketFailCount = (NexusState.ticketFailCount or 0) + 1\n                                        if NexusState.ticketFailCount == 5 then\n                                            NexusLib:Notify({ Title = "Quest", Message = "Claim failed 5 times. Check NPC or quest type.", Duration = 4 })\n                                        end\n                                    end\n                                else\n                                    NexusState.ticketFailCount = 0\n                                end\n                            end)\n                            task.wait(0.5)\n                        end\n                    end)\n                else\n                    if NexusState.autoClaimThread then\n                        task.cancel(NexusState.autoClaimThread)\n                        NexusState.autoClaimThread = nil\n                    end\n                    NexusState.ticketFailCount = 0\n                    NexusLib:Notify({ Title = "Quest", Message = "Auto claim stopped", Duration = 2 })\n                end\n            end\n        })\n    end\n\n    -- ===== DAILY QUESTS =====\n    do\n        local DailySection = QuestsTab:CreateSection("Daily Quests")\n        local dailyRunning = false\n        local dailyThread = nil\n\n        local function teleportToIsland(island)\n            if not island then return false end\n            local hrp = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")\n            if not hrp then return false end\n            local target = island.cframe.Position + Vector3.new(0, 5, 0)\n            hrp.AssemblyLinearVelocity = Vector3.zero\n            hrp.AssemblyAngularVelocity = Vector3.zero\n            hrp.CFrame = CFrame.new(target)\n            return true\n        end\n\n        local function doDailyQuest()\n            local userData = Data:FindFirstChild(tostring(LocalPlayer.UserId))\n            if not userData then\n                NexusLib:Notify({ Title = "Daily Quest", Message = "User data not found!", Duration = 2 })\n                return\n            end\n            local dailyFolder = userData:FindFirstChild("Quest") and userData.Quest:FindFirstChild("Daily")\n            if not dailyFolder then\n                NexusLib:Notify({ Title = "Daily Quest", Message = "Daily quest folder not found!", Duration = 2 })\n                return\n            end\n            local questFolders = {}\n            for _, child in pairs(dailyFolder:GetChildren()) do\n                if typeof(child) == "Instance" and typeof(child) == "Instance" and child:IsA("Folder") then\n                    table.insert(questFolders, child)\n                end\n            end\n            if #questFolders == 0 then\n                NexusLib:Notify({ Title = "Daily Quest", Message = "No daily quests available!", Duration = 2 })\n                return\n            end\n            local selectedFolder = questFolders[math.random(1, #questFolders)]\n            local questId = selectedFolder.Name\n            local progression = selectedFolder:FindFirstChild("Progression")\n            local questType = selectedFolder:FindFirstChild("QuestType")\n            if not progression or not questType then\n                NexusLib:Notify({ Title = "Daily Quest", Message = "Missing Progression or QuestType in quest " .. questId, Duration = 2 })\n                return\n            end\n            local currentProgress = (typeof(progression) == "Instance" and progression:IsA("NumberValue")) and progression.Value or 0\n            local qType = (typeof(questType) == "Instance" and questType:IsA("StringValue")) and questType.Value or ""\n\n            NexusLib:Notify({\n                Title = "Daily Quest",\n                Message = "Selected quest " .. questId .. " | Type: " .. qType .. " | Progress: " .. currentProgress,\n                Duration = 4\n            })\n\n            if qType == "PlayTime" then\n                NexusLib:Notify({ Title = "Daily Quest", Message = "PlayTime quest: just play for 30 minutes!", Duration = 3 })\n                return\n            end\n\n            if qType == "Fishing" then\n                local island = getRecommendedIsland()\n                if not island then\n                    NexusLib:Notify({ Title = "Daily Quest", Message = "No suitable island found!", Duration = 2 })\n                    return\n                end\n                if not teleportToIsland(island) then\n                    NexusLib:Notify({ Title = "Daily Quest", Message = "Teleport failed!", Duration = 2 })\n                    return\n                end\n                enableBasicFishing()\n                Fishing.Flags.AutoFarmBoss = false\n                Fishing.Flags.AutoFarmSecretBoss = false\n                NexusLib:Notify({ Title = "Daily Quest", Message = "Fishing daily started on " .. island.name, Duration = 2 })\n                while dailyRunning do\n                    local newProgress = selectedFolder:FindFirstChild("Progression")\n                    if typeof(newProgress) == "Instance" and newProgress:IsA("NumberValue") then\n                        if newProgress.Value >= 100 then\n                            NexusLib:Notify({ Title = "Daily Quest", Message = "Fishing daily completed!", Duration = 3 })\n                            break\n                        end\n                    end\n                    task.wait(2)\n                end\n            elseif qType == "BossQuest" then\n                local island = getRecommendedIsland()\n                if not island then\n                    NexusLib:Notify({ Title = "Daily Quest", Message = "No suitable island found!", Duration = 2 })\n                    return\n                end\n                if not teleportToIsland(island) then\n                    NexusLib:Notify({ Title = "Daily Quest", Message = "Teleport failed!", Duration = 2 })\n                    return\n                end\n                enableBasicFishing()\n                Fishing.Flags.AutoFarmBoss = true\n                Fishing.Flags.AutoFarmSecretBoss = false\n                NexusLib:Notify({ Title = "Daily Quest", Message = "Boss daily started on " .. island.name, Duration = 2 })\n                while dailyRunning do\n                    local newProgress = selectedFolder:FindFirstChild("Progression")\n                    if typeof(newProgress) == "Instance" and newProgress:IsA("NumberValue") then\n                        if newProgress.Value >= 10 then\n                            NexusLib:Notify({ Title = "Daily Quest", Message = "Boss daily completed!", Duration = 3 })\n                            break\n                        end\n                    end\n                    task.wait(2)\n                end\n            elseif qType == "Bait" then\n                NexusLib:Notify({ Title = "Daily Quest", Message = "Bait daily: buying Basic Bait...", Duration = 2 })\n                local buyEvent = Events:FindFirstChild("BuyBait")\n                if not buyEvent then\n                    NexusLib:Notify({ Title = "Daily Quest", Message = "BuyBait remote not found!", Duration = 2 })\n                    return\n                end\n                while dailyRunning do\n                    local newProgress = selectedFolder:FindFirstChild("Progression")\n                    if typeof(newProgress) == "Instance" and newProgress:IsA("NumberValue") then\n                        if newProgress.Value >= 25 then\n                            NexusLib:Notify({ Title = "Daily Quest", Message = "Bait daily completed!", Duration = 3 })\n                            break\n                        end\n                    end\n                    pcall(function() buyEvent:FireServer("Basic Bait", 1) end)\n                    task.wait(0.5)\n                end\n            else\n                NexusLib:Notify({ Title = "Daily Quest", Message = "Unknown quest type: " .. qType, Duration = 2 })\n            end\n            restoreRoutineFlags()\n        end\n\n        -- Toggle Auto Do Daily Quest\n        local autoDailyToggle = Cfg.register(DailySection:CreateToggle(Cfg.wrap("Toggle", "Auto Do Daily Quest", {\n            Name = "Auto Do Daily Quest",\n            Default = false,\n            Callback = function(value)\n                dailyRunning = value\n                if value then\n                    if dailyThread then\n                        task.cancel(dailyThread)\n                        dailyThread = nil\n                    end\n                    dailyThread = task.spawn(function()\n                        while dailyRunning do\n                            pcall(doDailyQuest)\n                            if dailyRunning then\n                                task.wait(5)\n                            end\n                        end\n                    end)\n                    NexusLib:Notify({ Title = "Daily Quest", Message = "Auto Daily started!", Duration = 2 })\n                else\n                    if dailyThread then\n                        task.cancel(dailyThread)\n                        dailyThread = nil\n                    end\n                    restoreRoutineFlags()\n                    NexusLib:Notify({ Title = "Daily Quest", Message = "Auto Daily stopped", Duration = 2 })\n                end\n            end\n        })), "Toggle", "Auto Do Daily Quest", {\n            Name = "Auto Do Daily Quest",\n            Default = false,\n            Callback = function(value)\n                dailyRunning = value\n                if value then\n                    if dailyThread then\n                        task.cancel(dailyThread)\n                        dailyThread = nil\n                    end\n              X", "C", "V"}\n                            for _, key in ipairs(selectedSkills) do\n                                if readySkills[key] then\n                                    Events.UseSkill:FireServer(key)\n                                end\n                            end\n                        end\n                    end\n                end)\n            else\n                NexusState.skillSeqIndex = 1\n            end\n            if Fishing.Flags.AntiAFK and tick() - (NexusState.lastAfkFire or 0) > 60 then\n                local _afkMoving = false\n                pcall(function()\n                    local _c = LocalPlayer.Character\n                    local _h = _c and _c:FindFirstChildOfClass("Humanoid")\n                    local _md = _h and _h.MoveDirection\n                    if _md and (math.abs(_md.X or 0) + math.abs(_md.Z or 0) > 0.05) then _afkMoving = true end\n                end)\n                if not _afkMoving then\n                    NexusState.lastAfkFire = tick()\n                    pcall(function() Events.AFK:FireServer() end)\n                end\n            end\n        end\n    end\nend)\n\n-- SMART SECRET WEATHER OVERRIDE LOOP\ntask.spawn(function()\n    local weatherIslandsMap = {\n        ["thunderstorm"] = "Island 2",\n        ["rainy"]        = "Island 3",\n        ["windy"]        = "Island 5",\n        ["snowy"]        = "Island 6",\n        ["frost"]        = "Island 6",\n        ["foggy"]        = "Island 7",\n        ["blazing sun"]  = "Island 8",\n    }\n\n    local function getActiveWeather()\n        local info = MainGui:FindFirstChild("Info")\n        if info then\n            local infoFrame = info:FindFirstChild("Info")\n            if infoFrame then\n                local weatherFrame = infoFrame:FindFirstChild("Weather")\n                if weatherFrame then\n                    local val = weatherFrame:FindFirstChild("Value")\n                    if val and typeof(val) == "Instance" then\n                        local text = ((typeof(val) == "Instance" and val:IsA("TextLabel") and val.Text or val.Value))\n                        return text:gsub("Weather:%s*", ""):lower():gsub("^%s+", ""):gsub("%s+$", "")\n                    end\n                end\n            end\n        end\n        return "clear"\n    end\n\n    while true do\n        task.wait(1.5)\n        if not alive() then break end\n        if NexusState.SmartWeather and NexusState.SmartWeather.enabled then\n            pcall(function()\n                local currentWeather = getActiveWeather()\n                local matchedIsland = weatherIslandsMap[currentWeather]\n\n                if matchedIsland and (currentWeather ~= "clear" and currentWeather ~= "") and NexusState.SmartWeather.selectedIslands[matchedIsland] then\n                    if not NexusState.SmartWeather.activeOverride then\n                        local char = LocalPlayer.Character\n                        local hrp = char and char:FindFirstChild("HumanoidRootPart")\n                        if hrp then\n                            NexusState.SmartWeather.savedCFrame = hrp.CFrame\n                            NexusState.SmartWeather.savedFlags = {\n                                AutoCast = Fishing.Flags.AutoCast,\n                                AutoFarmBoss = Fishing.Flags.AutoFarmBoss,\n                                AutoFarmSecretBoss = Fishing.Flags.AutoFarmSecretBoss,\n                                AnchorLock = Fishing.Flags.AnchorLock,\n                                AutoSkill = Fishing.Flags.AutoSkill,\n                                AutoSkillCheck = Fishing.Flags.AutoSkillCheck,\n                                AntiAFK = Fishing.Flags.AntiAFK,\n                            }\n                            NexusState.SmartWeather.activeOverride = true\n                            NexusState.SmartWeather.targetIsland = matchedIsland\n\n                            for _, v in ipairs(NexusState.islands) do\n                                if v.name:lower() == matchedIsland:lower() then\n                                    hrp.AssemblyLinearVelocity = Vector3.zero\n                                    hrp.AssemblyAngularVelocity = Vector3.zero\n                                    hrp.CFrame = CFrame.new(v.cframe.Position + Vector3.new(0, 5, 0))\n                                    break\n                                end\n                            end\n\n                            Fishing.Flags.AutoCast = false\n                            Fishing.Flags.AutoFarmBoss = false\n                            Fishing.Flags.AutoFarmSecretBoss = true\n                            Fishing.Flags.AnchorLock = true\n                            Fishing.Flags.AutoSkill = true\n                            Fishing.Flags.AutoSkillCheck = true\n                            Fishing.Flags.AntiAFK = true\n\n                            NexusLib:Notify({\n                                Title = "Farm On Weather",\n                                Message = "Weather detected: " .. currentWeather:upper() .. "! Auto-hopping to " .. matchedIsland .. " cau Secret.",\n                                Duration = 4\n                            })\n                        end\n                    end\n                else\n                    if NexusState.SmartWeather.activeOverride then\n                        NexusLib:Notify({\n                            Title = "Farm On Weather",\n                            Message = "Weather ended! Returning to the original farm...",\n                            Duration = 3\n                        })\n                        local char = LocalPlayer.Character\n                        local hrp = char and char:FindFirstChild("HumanoidRootPart")\n                        if NexusState.SmartWeather.savedCFrame and hrp then\n                            safeTeleport(hrp, NexusState.SmartWeather.savedCFrame)\n                        end\n                        if NexusState.SmartWeather.savedFlags then\n                            local s = NexusState.SmartWeather.savedFlags\n                            Fishing.Flags.AutoCast = s.AutoCast\n                            Fishing.Flags.AutoFarmBoss = s.AutoFarmBoss\n                            Fishing.Flags.AutoFarmSecretBoss = s.AutoFarmSecretBoss\n                            Fishing.Flags.AnchorLock = s.AnchorLock\n                            Fishing.Flags.AutoSkill = s.AutoSkill\n                            Fishing.Flags.AutoSkillCheck = s.AutoSkillCheck\n                            Fishing.Flags.AntiAFK = s.AntiAFK\n                        end\n                        NexusState.SmartWeather.activeOverride = false\n                        NexusState.SmartWeather.savedCFrame = nil\n                        NexusState.SmartWeather.savedFlags = nil\n                        NexusState.SmartWeather.targetIsland = nil\n                    end\n                end\n            end)\n        end\n    end\nend)\n\ntask.spawn(function()\n    while task.wait(1) do\n        if not alive() then break end\n        if bossFarmEnabled() then\n            local character = LocalPlayer.Character\n            local fishingGui = MainGui:FindFirstChild("Fishing")\n            if character and character:GetAttribute("Fishing") then\n                if Fishing.BossFarm.PendingCancel then\n                    cancelOrReleaseNormalFish()\n                elseif Fishing.BossFarm.HasHooked and fishingGui and fishingGui.Visible then\n                    local target = getCurrentHookTarget()\n                    local shouldFarm = shouldFarmBossTarget(target)\n                    if shouldFarm then\n                        Fishing.BossFarm.PendingCancel = false\n                        farmHookedBoss(target)\n                    elseif target.Name and target.Name ~= "???" then\n                        Fishing.BossFarm.PendingCancel = true\n                        cancelOrReleaseNormalFish()\n                    end\n                end\n            else\n                resetBossFarmTarget()\n                castRod()\n            end\n        end\n    end\nend)\n\n-- AUTO SELL\ndo\n    local function getInventoryCount()\n        local _icNow = tick()\n        if NexusState.cachedInvCount and NexusState.cachedInvCountAt and (_icNow - NexusState.cachedInvCountAt < 5) then\n            return NexusState.cachedInvCount\n        end\n        local userData = Data:FindFirstChild(tostring(LocalPlayer.UserId))\n        if not userData then return 0 end\n        local inv = userData:FindFirstChild("Inventory")\n        if not inv then return 0 end\n        local count = 0\n        for _ in pairs(inv:GetChildren()) do count = count + 1 end\n        NexusState.cachedInvCount = count\n        NexusState.cachedInvCountAt = _icNow\n        return count\n    end\n\n    local function getInventoryLimit()\n        local userData = Data:FindFirstChild(tostring(LocalPlayer.UserId))\n        if not userData then return 0 end\n        local limit = userData:FindFirstChild("InventoryLimit")\n        if limit and typeof(limit) == "Instance" and limit:IsA("NumberValue") then return limit.Value end\n        return 0\n    end\n\n    local function getSellSofa()\n        local map = Workspace:FindFirstChild("Map")\n        if map then\n            local map1 = map:FindFirstChild("Map 1")\n            if map1 then\n                local build = map1:FindFirstChild("Build")\n                if build then\n                    local sellFish = build:FindFirstChild("SellFish")\n                    if sellFish then\n                        return sellFish:FindFirstChild("Sofa")\n                    end\n                end\n            end\n        end\n        return nil\n    end\n\n    local function getSofaPosition()\n        local sofa = getSellSofa()\n        if sofa then\n            local hrp = sofa:FindFirstChild("HumanoidRootPart")\n            if hrp then return hrp.Position end\n            local primary = sofa.PrimaryPart\n            if primary then return primary.Position end\n            for _, part in ipairs(sofa:GetDescendants()) do\n                if typeof(part) == "Instance" and part:IsA("BasePart") then\n                    return part.Position\n                end\n            end\n        end\n        return nil\n    end\n\n    local function teleportToSofa()\n        local pos = getSofaPosition()\n        if not pos then return false end\n        local char = LocalPlayer.Character\n        if not char then return false end\n        local hrp = char:FindFirstChild("HumanoidRootPart")\n        if not hrp then return false end\n        NexusState.lastPosition = hrp.Position\n        hrp.CFrame = CFrame.new(pos + Vector3.new(0, 3, 0))\n        return true\n    end\n\n    local function teleportBack()\n        if not NexusState.lastPosition then return end\n        local char = LocalPlayer.Character\n        if not char then return end\n        local hrp = char:FindFirstChild("HumanoidRootPart")\n        if not hrp then return end\n        safeTeleport(hrp, CFrame.new(NexusState.lastPosition))\n        NexusState.lastPosition = nil\n    end\n\n    local function doSell()\n        if not MiscFlags.AutoSell then return end\n        if tick() - (NexusState.sellCooldown or 0) < 0.5 then return end\n        NexusState.sellCooldown = tick()\n        local method1 = NexusState.sellMethod1 or "Spam"\n        local method2 = NexusState.sellMethod2 or "Instant"\n        if method1 == "When full" then\n            local count = getInventoryCount()\n            local limit = getInventoryLimit()\n            if limit == 0 then return end\n            if count < limit - 3 then return end\n        end\n        local teleported = false\n        if method2 == "Teleport" then\n            teleported = teleportToSofa()\n            if teleported then task.wait(0.3) end\n        end\n        pcall(function() Events.SellFish:FireServer("All") end)\n        if teleported then\n  