tiAFK) then\n            if Fishing.Flags.AutoCast then\n                local c = LocalPlayer.Character\n                if c then\n                    -- Fix freeze: khong force cast khi player dang di chuyen\n                    local moving = false\n                    pcall(function()\n                        local hum = c:FindFirstChildOfClass("Humanoid")\n                        if hum and hum.MoveDirection then\n                            local md = hum.MoveDirection\n                            moving = math.abs(md.X or 0) + math.abs(md.Z or 0) > 0.05\n                        end\n                    end)\n                    if (not c:GetAttribute("Fishing")) and not moving and NexusState.canCastNow() then\n                        pcall(function() Events.Fishing:FireServer() end)\n                    elseif NexusState.isDoingUseBaitQuest and MainGui:FindFirstChild("Fishing") and MainGui.Fishing.Visible then\n                        pcall(function()\n                            local root = c:FindFirstChild("HumanoidRootPart")\n                            Events.Fishing:FireServer(root and root.CFrame or nil)\n                        end)\n                    end\n                end\n            end\n            if Fishing.Flags.AutoSkill and MainGui:FindFirstChild("Fishing") and MainGui.Fishing.Visible then\n                pcall(function()\n                    local char = LocalPlayer.Character\n                    local skillsFolder = char and char:FindFirstChild("Skills")\n                    if skillsFolder then\n                        local readySkills = {}\n                        for _, skill in ipairs(skillsFolder:GetChildren()) do\n                            if typeof(skill) == "Instance" and skill:IsA("NumberValue") and skill.Value <= 0 then\n                                local key = skill:GetAttribute("Key")\n                                if key then readySkills[key] = true end\n                            end\n                        end\n\n                        if Fishing.Flags.SkillMode == "Sequential" then\n                            local now = tick()\n                            local delay = Fishing.Flags.SkillDelay or 0.3\n                            if now - (NexusState.lastSkillCastTime or 0) >= delay then\n                                local seqStr = Fishing.Flags.SkillSequence or "Z,X,C,V"\n                                local seq = {}\n                                for k in string.gmatch(seqStr:upper(), "[ZXCV]") do\n                                    table.insert(seq, k)\n                                end\n                                if #seq == 0 then seq = {"Z", "X", "C", "V"} end\n\n                                local attempts = 0\n                                while attempts < #seq do\n                                    attempts = attempts + 1\n                                    if not NexusState.skillSeqIndex or NexusState.skillSeqIndex > #seq then\n                                        NexusState.skillSeqIndex = 1\n                                    end\n                                    local targetKey = seq[NexusState.skillSeqIndex]\n                                    NexusState.skillSeqIndex = NexusState.skillSeqIndex + 1\n                                    if readySkills[targetKey] then\n                                        Events.UseSkill:FireServer(targetKey)\n                                        NexusState.lastSkillCastTime = now\n                                        break\n                                    end\n                                end\n                            end\n                        else\n                            local selectedSkills = Fishing.Flags.SelectedSkills or {"Z", "X", "C", "V"}\n                            for _, key in ipairs(selectedSkills) do\n                                if readySkills[key] then\n                                    Events.UseSkill:FireServer(key)\n                                end\n                            end\n                        end\n                    end\n                end)\n            else\n                NexusState.skillSeqIndex = 1\n            end\n            if Fishing.Flags.AntiAFK and tick() - (NexusState.lastAfkFire or 0) > 60 then\n                local _afkMoving = false\n                pcall(function()\n                    local _c = LocalPlayer.Character\n                    local _h = _c and _c:FindFirstChildOfClass("Humanoid")\n                    local _md = _h and _h.MoveDirection\n                    if _md and (math.abs(_md.X or 0) + math.abs(_md.Z or 0) > 0.05) then _afkMoving = true end\n                end)\n                if not _afkMoving then\n                    NexusState.lastAfkFire = tick()\n                    pcall(function() Events.AFK:FireServer() end)\n                end\n            end\n        end\n    end\nend)\n\n-- SMART SECRET WEATHER OVERRIDE LOOP\ntask.spawn(function()\n    local weatherIslandsMap = {\n        ["thunderstorm"] = "Island 2",\n        ["rainy"]        = "Island 3",\n        ["windy"]        = "Island 5",\n        ["snowy"]        = "Island 6",\n        ["frost"]        = "Island 6",\n        ["foggy"]        = "Island 7",\n        ["blazing sun"]  = "Island 8",\n    }\n\n    local function getActiveWeather()\n        local info = MainGui:FindFirstChild("Info")\n        if info then\n            local infoFrame = info:FindFirstChild("Info")\n            if infoFrame then\n                local weatherFrame = infoFrame:FindFirstChild("Weather")\n                if weatherFrame then\n                    local val = weatherFrame:FindFirstChild("Value")\n                    if val and typeof(val) == "Instance" then\n                        local text = ((typeof(val) == "Instance" and val:IsA("TextLabel") and val.Text or val.Value))\n                        return text:gsub("Weather:%s*", ""):lower():gsub("^%s+", ""):gsub("%s+$", "")\n                    end\n                end\n            end\n        end\n        return "clear"\n    end\n\n    while true do\n        task.wait(1.5)\n        if not alive() then break end\n        if NexusState.SmartWeather and NexusState.SmartWeather.enabled then\n            pcall(function()\n                local currentWeather = getActiveWeather()\n                local matchedIsland = weatherIslandsMap[currentWeather]\n\n                if matchedIsland and (currentWeather ~= "clear" and currentWeather ~= "") and NexusState.SmartWeather.selectedIslands[matchedIsland] then\n                    if not NexusState.SmartWeather.activeOverride then\n                        local char = LocalPlayer.Character\n                        local hrp = char and char:FindFirstChild("HumanoidRootPart")\n                        if hrp then\n                            NexusState.SmartWeather.savedCFrame = hrp.CFrame\n                            NexusState.SmartWeather.savedFlags = {\n                                AutoCast = Fishing.Flags.AutoCast,\n                                AutoFarmBoss = Fishing.Flags.AutoFarmBoss,\n                                AutoFarmSecretBoss = Fishing.Flags.AutoFarmSecretBoss,\n                                AnchorLock = Fishing.Flags.AnchorLock,\n                                AutoSkill = Fishing.Flags.AutoSkill,\n                                AutoSkillCheck = Fishing.Flags.AutoSkillCheck,\n                                AntiAFK = Fishing.Flags.AntiAFK,\n                            }\n                            NexusState.SmartWeather.activeOverride = true\n                            NexusState.SmartWeather.targetIsland = matchedIsland\n\n                            for _, v in ipairs(NexusState.islands) do\n                                if v.name:lower() == matchedIsland:lower() then\n                                    hrp.AssemblyLinearVelocity = Vector3.zero\n                                    hrp.AssemblyAngularVelocity = Vector3.zero\n                                    hrp.CFrame = CFrame.new(v.cframe.Position + Vector3.new(0, 5, 0))\n                                    break\n                                end\n                            end\n\n                            Fishing.Flags.AutoCast = false\n                            Fishing.Flags.AutoFarmBoss = false\n                            Fishing.Flags.AutoFarmSecretBoss = true\n                            Fishing.Flags.AnchorLock = true\n                            Fishing.Flags.AutoSkill = true\n                            Fishing.Flags.AutoSkillCheck = true\n                            Fishing.Flags.AntiAFK = true\n\n                            NexusLib:Notify({\n                                Title = "Farm On Weather",\n                                Message = "Weather detected: " .. currentWeather:upper() .. "! Auto-hopping to " .. matchedIsland .. " cau Secret.",\n                                Duration = 4\n                            })\n                        end\n                    end\n                else\n                    if NexusState.SmartWeather.activeOverride then\n                        NexusLib:Notify({\n                            Title = "Farm On Weather",\n                            Message = "Weather ended! Returning to the original farm...",\n                            Duration = 3\n                        })\n                        local char = LocalPlayer.Character\n                        local hrp = char and char:FindFirstChild("HumanoidRootPart")\n                        if NexusState.SmartWeather.savedCFrame and hrp then\n                            safeTeleport(hrp, NexusState.SmartWeather.savedCFrame)\n                        end\n                        if NexusState.SmartWeather.savedFlags then\n                            local s = NexusState.SmartWeather.savedFlags\n                            Fishing.Flags.AutoCast = s.AutoCast\n                            Fishing.Flags.AutoFarmBoss = s.AutoFarmBoss\n                            Fishing    local direct = tonumber(s)\n    if direct then return direct end\n    local num, suffix = s:match("^([%d%.]+)%s*([KkMmBbTt])%+?$")\n    num = tonumber(num)\n    if not num then return nil end\n    local mult = { K = 1000, M = 1000000, B = 1000000000, T = 1000000000000 }\n    local m = mult[string.upper(suffix or "")]\n    if not m then return nil end\n    return num * m\nend\n\nlocal function parseCraftFishEntry(item)\n    if not item then return nil, nil, 0 end\n    local rawName = tostring(item.Name or "")\n    rawName = string.split(rawName, "| Favorite")[1]\n    local count = 1\n    pcall(function()\n        if type(item.Value) == "number" then count = item.Value end\n    end)\n    local parts = {}\n    for part in string.gmatch(rawName, "[^|]+") do table.insert(parts, part) end\n    local function trim(s) return tostring(s or ""):gsub("^%s+", ""):gsub("%s+$", "") end\n    local fishName = trim(parts[1])\n    local weight = nil\n    if #parts >= 2 then\n        weight = parseCraftWeight(string.split(trim(parts[2]), " ")[1])\n    end\n    if not weight then\n        pcall(function()\n            local w = item:GetAttribute("Weight")\n            if type(w) == "number" and w > 0 then weight = w end\n        end)\n    end\n    if (not weight) and type(item.Value) == "string" and string.find(item.Value, "|", 1, true) then\n        local vparts = {}\n        for part in string.gmatch(item.Value, "[^|]+") do table.insert(vparts, part) end\n        if #vparts >= 2 then\n            weight = parseCraftWeight(string.split(trim(vparts[2]), " ")[1])\n        end\n        if fishName == "" and #vparts >= 1 then fishName = trim(vparts[1]) end\n    end\n    if fishName == "" then return nil, nil, 0 end\n    if type(count) ~= "number" or count < 1 then count = 1 end\n    return fishName, weight, math.floor(count)\nend\n\nlocal function GetBuyableBaits()\n    local _bbNow = tick()\n    if NexusState.cachedBuyableBaits and NexusState.cachedBuyableBaitsAt and (_bbNow - NexusState.cachedBuyableBaitsAt < 30) then\n        return NexusState.cachedBuyableBaits\n    end\n    local baits = {}\n    if not Info or not Info:FindFirstChild("Bait") then return {"No bait available"} end\n    for _, child in pairs(Info.Bait:GetChildren()) do\n        if typeof(child) == "Instance" and typeof(child) == "Instance" and child:IsA("ModuleScript") then\n            local success, mod = pcall(require, child)\n            if success and type(mod) == "table" and mod.Price and mod.Price > 0 then\n                table.insert(baits, child.Name)\n            end\n        end\n    end\n    if #baits == 0 then return {"No bait available"} end\n    NexusState.cachedBuyableBaits = baits\n    NexusState.cachedBuyableBaitsAt = _bbNow\n    return baits\nend\n\nlocal function saveRoutineFlags()\n    NexusState.savedRoutineFlags = {\n        AutoCast = Fishing.Flags.AutoCast,\n        AnchorLock = Fishing.Flags.AnchorLock,\n        AutoSkill = Fishing.Flags.AutoSkill,\n        AutoSell = MiscFlags.AutoSell,\n        AutoSkillCheck = Fishing.Flags.AutoSkillCheck,\n        AntiAFK = Fishing.Flags.AntiAFK,\n        AutoFarmBoss = Fishing.Flags.AutoFarmBoss,\n        AutoFarmSecretBoss = Fishing.Flags.AutoFarmSecretBoss,\n        AutoBuy = MiscFlags.AutoBuy,\n        AutoEquipBait = MiscFlags.AutoEquipBait,\n        AutoEquipRod = MiscFlags.AutoEquipRod,\n    }\nend\n\nlocal function restoreRoutineFlags()\n    if NexusState.savedRoutineFlags then\n        Fishing.Flags.AutoCast = NexusState.savedRoutineFlags.AutoCast\n        Fishing.Flags.AnchorLock = NexusState.savedRoutineFlags.AnchorLock\n        Fishing.Flags.AutoSkill = NexusState.savedRoutineFlags.AutoSkill\n        MiscFlags.AutoSell = NexusState.savedRoutineFlags.AutoSell\n        Fishing.Flags.AutoSkillCheck = NexusState.savedRoutineFlags.AutoSkillCheck\n        Fishing.Flags.AntiAFK = NexusState.savedRoutineFlags.AntiAFK\n        Fishing.Flags.AutoFarmBoss = NexusState.savedRoutineFlags.AutoFarmBoss\n        Fishing.Flags.AutoFarmSecretBoss = NexusState.savedRoutineFlags.AutoFarmSecretBoss\n        MiscFlags.AutoBuy = NexusState.savedRoutineFlags.AutoBuy\n        MiscFlags.AutoEquipBait = NexusState.savedRoutineFlags.AutoEquipBait\n        MiscFlags.AutoEquipRod = NexusState.savedRoutineFlags.AutoEquipRod\n        NexusState.savedRoutineFlags = nil\n    else\n        Fishing.Flags.AutoFarmBoss = false\n        Fishing.Flags.AutoFarmSecretBoss = false\n    end\nend\n\n-- Ticket fishing mode: auto cast + anchor lock + auto skill + rod equip,\n-- so turning on Auto Do Ticket is enough to work all 8 ticket quests.\nlocal function enableBasicFishing()\n    if not NexusState.savedRoutineFlags then saveRoutineFlags() end\n    Fishing.Flags.AutoCast = true\n    Fishing.Flags.AnchorLock = true\n    Fishing.Flags.AutoSkill = true\n    Fishing.Flags.AutoSkillCheck = true\n    MiscFlags.AutoEquipRod = true\nend\n\nlocal function disableAllFishing()\n    restoreRoutineFlags()\nend\n\n-- Teleport without the sky-drop freeze: a character held at +1000 sky sits in\n-- freefall, so AssemblyLinearVelocity grows huge. Carrying that velocity into a\n-- ground teleport slams the Humanoid into the floor and sticks it (frozen).\n-- Zero it on both ends and wake the Humanoid so movement resumes instantly.\nlocal function safeTeleport(hrp, cf)\n    if not hrp or not cf then return end\n    local model = hrp.Parent\n    local humanoid = model and model:FindFirstChildOfClass("Humanoid")\n    -- Never freeze the live character: Anchored + task.wait() inside a\n    -- RenderStepped/Heartbeat-adjacent call stalls physics for a frame and\n    -- leaves the Humanoid seated/stuck, so walking looks frozen afterwards.\n    -- PivotTo moves the whole model atomically with no Anchored pin.\n    local ok = false\n    if model then\n        pcall(function()\n            model:PivotTo(cf)\n            ok = true\n        end)\n    end\n    if not ok then\n        pcall(function()\n            hrp.AssemblyLinearVelocity = Vector3.zero\n            hrp.AssemblyAngularVelocity = Vector3.zero\n            hrp.CFrame = cf\n        end)\n    end\n    pcall(function()\n        hrp.Anchored = false\n        hrp.AssemblyLinearVelocity = Vector3.zero\n        hrp.AssemblyAngularVelocity = Vector3.zero\n    end)\n    if humanoid then\n        pcall(function()\n            if humanoid.Seated then humanoid.Seated = false end\n            humanoid:ChangeState(Enum.HumanoidStateType.GettingUp)\n        end)\n    end\nend\n\n-- ===== EGO + TIGER CHECK (dieu kien cho Island 11) =====\n-- Island 11 chi duoc recommend khi user co ca rod Ego va Tiger trong kho.\nlocal function hasEgoAndTiger()\n    local p = GetPlayerData()\n    if not p then return false end\n    local rodFolder = p:FindFirstChild("FishingRodInventory") or p:FindFirstChild("Rod")\n    if not rodFolder then return false end\n    local hasEgo, hasTiger = false, false\n    for _, f in pairs(rodFolder:GetChildren()) do\n        local n = string.lower(tostring(f.Name))\n        if string.find(n, "ego") then hasEgo = true end\n        if string.find(n, "tiger") then hasTiger = true end\n    end\n    return hasEgo and hasTiger\nend\n\nlocal function getTotalPower()\n    local _pwNow = tick()\n    if NexusState.cachedPower and NexusState.cachedPowerAt and (_pwNow - NexusState.cachedPowerAt < 5) then\n        return NexusState.cachedPower\n    end\n    local total = 0\n    local char = LocalPlayer.Character\n    if char then\n        local stats = char:FindFirstChild("Stats")\n        if stats then\n            local rp = stats:FindFirstChild("RodPower")\n            if typeof(rp) == "Instance" and rp:IsA("NumberValue") then total = total + rp.Value end\n            local fp = stats:FindFirstChild("FishPower")\n            if typeof(fp) == "Instance" and fp:IsA("NumberValue") then total = total + fp.Value end\n        end\n        local attr = char:GetAttribute("RodPower")\n        if attr and type(attr) == "number" and attr > 0 and total == 0 then total = attr end\n    end\n    if total == 0 then\n        local userId = LocalPlayer.UserId\n        local userData = Data:FindFirstChild(tostring(userId))\n        if userData then\n            local rodNameValue = userData:FindFirstChild("FishingRod")\n            if rodNameValue then\n                local rodName = rodNameValue.Value\n                if rodName and rodName ~= "" then\n                    local rodModule = Info:FindFirstChild("Inventory") and Info.Inventory:FindFirstChild(rodName)\n                    if rodModule then\n                        local success, rodData = pcall(require, rodModule)\n                        if success and type(rodData) == "table" then\n                            total = rodData.Power or 0\n                        end\n                    end\n                end\n            end\n        end\n    end\n    NexusState.cachedPower = total\n    NexusState.cachedPowerAt = _pwNow\n    return total\nend\n\nlocal function getRecommendedIsland()\n    local _rcNow = tick()\n    if NexusState.cachedRecommended and NexusState.cachedRecommendedAt and (_rcNow - NexusState.cachedRecommendedAt < 5) then\n        return NexusState.cachedRecommended\n    end\n    local currentPower = getTotalPower()\n    local eligible = {}\n    for _, island in ipairs(NexusState.islands) do\n        -- Island 11 (if u have ego and tiger): chi chon khi co ca rod Ego va Tiger\n        if island.name ~= "Island 11" or hasEgoAndTiger() then\n            if (island.power or 0) <= currentPower then\n                table.insert(eligible, island)\n            end\n        end\n    end\n    table.sort(eligible, function(a, b) return a.power > b.power end)\n    NexusState.cachedRecommended = eligible[2] or eligible[1]\n    NexusState.cachedRecommendedAt = _rcNow\n    return NexusState.cachedRecommended\nend\n\nlocal function isHoldingFishingRod()\n    local char = LocalPlayer.Character\n    if not char then return false end\n    local typ = char:GetAttribute("Type")\n    if typ and string.lower(tostring(typ)) == "fishing rod" then return true end\n    return false\nend\n\n-- ============================================================\n\n-- ============================================================\n-- ===== CONFIG SYSTEM (save / load / auto-load / import-export) =====\n-- ============================================================\n-- Every Toggle / Dropdown / MultiDropdown / Textbox with a static English Name is\n-- registered here through Cfg.wrap(kind, name, config) at creation time. The config\n-- table itself is untouched (defaults still come from Default = ...), the registry\n-- only keeps the live handle so save/load can Get/Set values later.\n--\n-- Save format is a flat { [controlName] = value } table, JSON-encoded. Control\n-- names are unique across the whole hub (verified), so no tab/section prefix is\n-- needed and configs stay compatible even if a control moves sections.\ndo\n    local ConfigSys = {}\n    ConfigSys.registry = {}   -- [name] = { kind = "toggle"|"dropdown"|"multi"|"text", get = fn, set = fn }\n    ConfigSys.ordered = {}    -- registration order, for stable exports\n    ConfigSys.FILE = "NexusHub_Config.json"\n    ConfigSys.AUTO_FILE = "NexusHub_AutoLoad.json"\n    ConfigSys._saving = false\n\n    local function cfgKind(callKind)\n        if callKind == "Toggle" then return "toggle" end\n        if callKind == "Dropdown" then return "dropdown" end\n        if callKind == "MultiDropdown" then return "multi" end\n        return "text"\n    end\n\n    -- Wrap a control config table: pass through untouched, remember the name so\n    -- the returned handle can be registered right after creation.\n    function ConfigSys.wrap(callKind, name, config)\n        config = config or {}\n        config._CfgKind = callKind\n        config._CfgName = name\n        return config\n    end\n\n    function ConfigSys.register(handle, callKind, name, config)\n        if