\n                        local root = char:FindFirstChild("HumanoidRootPart")\n                        if root then\n                            root.CFrame = CFrame.new(NexusState.learnSkill.oldPosition)\n                            NexusState.learnSkill.oldPosition = nil\n                            NexusState.learnSkill.teleported = false\n                        end\n                    end\n                end\n                NexusLib:Notify({ Title = "Learn Skills", Message = "Learned " .. learnedCount .. " skill(s)!", Duration = 3 })\n            end\n        })\n    end\n\n    -- Trait Reroll\n    do\n        local TraitSection = ShopTab:CreateSection("Trait Reroll")\n        local function GetOwnedSkillNames()\n            local p = Data and Data:FindFirstChild(tostring(LocalPlayer.UserId))\n            if not p then return {"No skill owned"} end\n            local skills = {}\n            for _, f in pairs(p.Skill:GetChildren()) do\n                if typeof(f) == "Instance" and typeof(f) == "Instance" and f:IsA("Folder") and f.Owned and f.Owned.Value == true then\n                    table.insert(skills, f.Name)\n                end\n            end\n            if #skills == 0 then return {"No skill owned"} end\n            return skills\n        end\n\n        local function GetTraitNames()\n            local traits = {}\n            if not Info or not Info:FindFirstChild("Trait") then return {"No trait available"} end\n            for _, child in pairs(Info.Trait:GetChildren()) do\n                if typeof(child) == "Instance" and typeof(child) == "Instance" and child:IsA("ModuleScript") then\n                    local ok, mod = pcall(require, child)\n                    if ok and type(mod) == "table" and mod.Name then\n                        table.insert(traits, mod.Name)\n                    end\n                end\n            end\n            if #traits == 0 then return {"No trait available"} end\n            return traits\n        end\n\n        local ownedSkills = GetOwnedSkillNames()\n        local selectedSkillForReroll = ownedSkills[1] or "No skill owned"\n        local traitNames = GetTraitNames()\n        local selectedTargetTrait = traitNames[1] or "No trait available"\n        local ignoreLocked = false\n\n        local traitSkillDropdown = Cfg.register(TraitSection:CreateDropdown(Cfg.wrap("Dropdown", "Select Skill", {\n            Name = "Select Skill",\n            Options = ownedSkills,\n            Default = selectedSkillForReroll,\n            Callback = function(value) selectedSkillForReroll = value end\n        })), "Dropdown", "Select Skill", {\n            Name = "Select Skill",\n            Options = ownedSkills,\n            Default = selectedSkillForReroll,\n            Callback = function(value) selectedSkillForReroll = value end\n        })\n\n        local targetTraitDropdown = Cfg.register(TraitSection:CreateDropdown(Cfg.wrap("Dropdown", "Target Trait", {\n            Name = "Target Trait",\n            Options = traitNames,\n            Default = selectedTargetTrait,\n            Callback = function(value) selectedTargetTrait = value end\n        })), "Dropdown", "Target Trait", {\n            Name = "Target Trait",\n            Options = traitNames,\n            Default = selectedTargetTrait,\n            Callback = function(value) selectedTargetTrait = value end\n        })\n\n        local ignoreLockedToggle = Cfg.register(TraitSection:CreateToggle(Cfg.wrap("Toggle", "Ignore Locked", {\n            Name = "Ignore Locked",\n            Default = false,\n            Callback = function(value) ignoreLocked = value end\n        })), "Toggle", "Ignore Locked", {\n            Name = "Ignore Locked",\n            Default = false,\n            Callback = function(value) ignoreLocked = value end\n        })\n\n        local rerollMethodDropdown = Cfg.register(TraitSection:CreateDropdown(Cfg.wrap("Dropdown", "Reroll Method", {\n            Name = "Reroll Method",\n            Options = {"Instant", "Teleport"},\n            Default = NexusState.Reroll.method or "Instant",\n            Callback = function(value) NexusState.Reroll.method = value end\n        })), "Dropdown", "Reroll Method", {\n            Name = "Reroll Method",\n            Options = {"Instant", "Teleport"},\n            Default = NexusState.Reroll.method or "Instant",\n            Callback = function(value) NexusState.Reroll.method = value end\n        })\n\n        local RerollTrait = Events:FindFirstChild("RerollTrait")\n\n        TraitSection:CreateButton({\n            Name = "Reroll Until Trait",\n            Callback = function()\n                if NexusState.Reroll.running then\n                    NexusState.Reroll.running = false\n                    if NexusState.Reroll.thread then\n                        task.cancel(NexusState.Reroll.thread)\n                        NexusState.Reroll.thread = nil\n                    end\n                    if NexusState.Reroll.teleported and NexusState.Reroll.oldPosition then\n                        local char = LocalPlayer.Character\n                        if char then\n                            local root = char:FindFirstChild("HumanoidRootPart")\n                            if root then\n                                root.CFrame = CFrame.new(NexusState.Reroll.oldPosition)\n                                NexusState.Reroll.oldPosition = nil\n                                NexusState.Reroll.teleported = false\n                            end\n                        end\n                    end\n                    NexusLib:Notify({ Title = "Reroll", Message = "Stopped", Duration = 2 })\n                    return\n                end\n\n                local skillName = selectedSkillForReroll\n                local targetTrait = selectedTargetTrait\n                if not skillName or skillName == "" or skillName == "No skill owned" then\n                    NexusLib:Notify({ Title = "Reroll", Message = "Select a valid skill", Duration = 2 })\n                    return\n                end\n                if not targetTrait or targetTrait == "" or targetTrait == "No trait available" then\n                    NexusLib:Notify({ Title = "Reroll", Message = "Select a target trait", Duration = 2 })\n                    return\n                end\n                if not RerollTrait then\n                    NexusLib:Notify({ Title = "Reroll", Message = "RerollTrait event not found", Duration = 2 })\n                    return\n                end\n                local p = Data and Data:FindFirstChild(tostring(LocalPlayer.UserId))\n                local rerollCount = p and p:FindFirstChild("Trait Reroll")\n                if rerollCount and rerollCount.Value <= 0 then\n                    NexusLib:Notify({ Title = "Reroll", Message = "No rerolls left!", Duration = 2 })\n                    return\n                end\n\n                NexusState.Reroll.teleported = false\n                NexusState.Reroll.oldPosition = nil\n                if NexusState.Reroll.method == "Teleport" then\n                    local npc = Workspace:FindFirstChild("NPC")\n                    if npc then\n                        local func = npc:FindFirstChild("Function")\n                        if func then\n                            local nanjiang = func:FindFirstChild("Nanjiang")\n                            if typeof(nanjiang) == "Instance" and nanjiang:IsA("Model") then\n                                local hrp = nanjiang:FindFirstChild("HumanoidRootPart")\n                                if hrp then\n                                    local char = LocalPlayer.Character\n                                    if char then\n                                        local root = char:FindFirstChild("HumanoidRootPart")\n                                        if root then\n                                            NexusState.Reroll.oldPosition = root.Position\n                                            root.CFrame = CFrame.new(hrp.Position + Vector3.new(0, 3, 0))\n                                            NexusState.Reroll.teleported = true\n                                            task.wait(0.3)\n                                        end\n                                    end\n                                end\n                            end\n                        end\n                    end\n                    if not NexusState.Reroll.teleported then\n                        NexusLib:Notify({ Title = "Reroll", Message = "Could not find Nanjiang, teleport failed. Continuing anyway.", Duration = 3 })\n                    end\n                end\n\n                NexusState.Reroll.running = true\n                NexusLib:Notify({ Title = "Reroll", Message = "Reroll started... Target: " .. targetTrait, Duration = 2 })\n\n                NexusState.Reroll.thread = task.spawn(function()\n                    local successCount = 0\n                    while NexusState.Reroll.running do\n                        local p2 = Data and Data:FindFirstChild(tostring(LocalPlayer.UserId))\n                        local count = p2 and p2:FindFirstChild("Trait Reroll")\n                        if count and count.Value <= 0 then\n                            NexusLib:Notify({ Title = "Reroll", Message = "No rerolls left, stopping", Duration = 2 })\n                            break\n                        end\n                        local success, result = pcall(function()\n                            return RerollTrait:InvokeServer(skillName, ignoreLocked)\n                        end)\n                        if not success or not result then\n                            NexusLib:Notify({ Title = "Reroll", Message = "Reroll failed, stopping", Duration = 2 })\n                            break\n                        end\n                        successCount = successCount + 1\n                        local traitName = result.Name\n                        if traitName == targetTrait then\n                            NexusLib:Notify({ Title = "Reroll", Message = "Got " .. targ  local pg = LocalPlayer:FindFirstChild("PlayerGui")\n        if pg then\n            applyLanguageToGui(pg:FindFirstChild("NexusPanel"))\n            applyLanguageToGui(pg:FindFirstChild("NexusNotifications"))\n        end\n        pcall(function()\n            local cg = game:GetService("CoreGui")\n            if cg then\n                applyLanguageToGui(cg:FindFirstChild("NexusPanel"))\n                applyLanguageToGui(cg:FindFirstChild("NexusNotifications"))\n            end\n        end)\n    end\n\n    function I18n.initListeners()\n        local function hookGui(gui)\n            if not gui then return end\n            gui.DescendantAdded:Connect(function(desc)\n                task.wait(0.03)\n                translateObject(desc)\n            end)\n        end\n\n        local pg = LocalPlayer:FindFirstChild("PlayerGui")\n        if pg then\n            local panel = pg:FindFirstChild("NexusPanel")\n            if panel then hookGui(panel) end\n            local notifs = pg:FindFirstChild("NexusNotifications")\n            if notifs then hookGui(notifs) end\n\n            pg.ChildAdded:Connect(function(child)\n                if child.Name == "NexusPanel" or child.Name == "NexusNotifications" then\n                    hookGui(child)\n                    task.wait(0.1)\n                    applyLanguageToGui(child)\n                end\n            end)\n        end\n\n        pcall(function()\n            local cg = game:GetService("CoreGui")\n            if cg then\n                local panel = cg:FindFirstChild("NexusPanel")\n                if panel then hookGui(panel) end\n                local notifs = cg:FindFirstChild("NexusNotifications")\n                if notifs then hookGui(notifs) end\n\n                cg.ChildAdded:Connect(function(child)\n                    if child.Name == "NexusPanel" or child.Name == "NexusNotifications" then\n                        hookGui(child)\n                        task.wait(0.1)\n                        applyLanguageToGui(child)\n                    end\n                end)\n            end\n        end)\n    end\nend\n\n-- ===== FAKE NAME (STREAMER MODE) CORE =====\n-- ============================================================\ndo\n    local realName = LocalPlayer.Name\n    local realDisplayName = LocalPlayer.DisplayName\n    local fakeNameConn = nil\n    local fakeNameThread = nil\n    local maskIdsInText -- forward declare (dinh nghia ben duoi)\n\n    local function replacePlain(text, find, repl)\n        if find == "" then return text end\n        local parts = {}\n        local start = 1\n        while true do\n            local s, e = string.find(text, find, start, true)\n            if not s then\n                table.insert(parts, string.sub(text, start))\n                break\n            end\n            table.insert(parts, string.sub(text, start, s - 1))\n            table.insert(parts, repl)\n            start = e + 1\n        end\n        return table.concat(parts)\n    end\n\n    local function replaceTextInObject(obj)\n        if not NexusState.fakeNameEnabled then return end\n        if not obj or typeof(obj) ~= "Instance" then return end\n        pcall(function()\n            if typeof(obj) == "Instance" and typeof(obj) == "Instance" and obj:IsA("TextLabel") or obj:IsA("TextButton") or obj:IsA("TextBox") then\n                local text = obj.Text\n                if text and #text > 0 then\n                    local updated = false\n                    if realDisplayName ~= "" and string.find(text, realDisplayName, 1, true) then\n                        text = replacePlain(text, realDisplayName, NexusState.fakeDisplayName or "NexusPlayer")\n                        updated = true\n                    end\n                    if realName ~= "" and string.find(text, realName, 1, true) then\n                        text = replacePlain(text, realName, NexusState.fakeName or "NexusPlayer")\n                        updated = true\n                    end\n                    -- Guild display: doi ten guild that -> fake guild de khong bi ban\n                    if NexusState.realGuildName and #NexusState.realGuildName > 0 then\n                        local rg = tostring(NexusState.realGuildName)\n                        if rg ~= "ZION" and not string.find(text, "ZION", 1, true) and string.find(text, rg, 1, true) then\n                            text = replacePlain(text, rg, NexusState.fakeGuildName or "NexusGuild")\n                            updated = true\n                        end\n                    end\n                    -- Che luon ID (UserId / PlaceId / JobId) chu khong chi ten\n                    if maskIdsInText then\n                        local masked, idChanged = maskIdsInText(text)\n                        if idChanged then\n                            text = masked\n                            updated = true\n                        end\n                    end\n                    if updated then\n                        obj.Text = text\n                    end\n                end\n            end\n        end)\n    end\n\n    -- Che ID: doi ten khong thoi van bi report vi nguoi ta doc UserId / PlaceId /\n    -- JobId tren man hinh (hoac trong anh chup). Nen phai che luon cac ID nay.\n    local realUserId = tostring(LocalPlayer.UserId)\n    local realPlaceId = tostring(game.PlaceId)\n\n    function maskIdsInText(text)\n        if not NexusState.fakeNameEnabled then return text, false end\n        local changed = false\n        if #realUserId >= 5 and string.find(text, realUserId, 1, true) then\n            if (NexusState.fakeIdMode or 1) == 2 then\n                text = string.gsub(text, realUserId, "****")\n            else\n                text = string.gsub(text, realUserId, tostring(NexusState.fakeUserId or "0"))\n            end\n            changed = true\n        end\n        if #realPlaceId >= 5 and string.find(text, realPlaceId, 1, true) then\n            text = string.gsub(text, realPlaceId, "0000000000")\n            changed = true\n        end\n        local guidPat = "%x%x%x%x%x%x%x%x%-%x%x%x%x%-%x%x%x%x%-%x%x%x%x%-%x%x%x%x%x%x%x%x%x%x%x%x"\n        if string.find(text, guidPat) then\n            text = string.gsub(text, guidPat, "********-****-****-****-************")\n            changed = true\n        end\n        return text, changed\n    end\n\n    local function applyFakeNameToAll()\n        if not NexusState.fakeNameEnabled then return end\n        local pg = LocalPlayer:FindFirstChild("PlayerGui")\n        if pg then\n            for _, v in ipairs(pg:GetDescendants()) do\n                replaceTextInObject(v)\n            end\n        end\n        local char = LocalPlayer.Character\n        if char then\n            for _, v in ipairs(char:GetDescendants()) do\n                replaceTextInObject(v)\n            end\n        end\n        pcall(function()\n            local cg = game:GetService("CoreGui")\n            if cg then\n                for _, v in ipairs(cg:GetDescendants()) do\n                    replaceTextInObject(v)\n                end\n            end\n        end)\n    end\n\n    function NexusState.enableFakeName()\n        if NexusState.fakeNameEnabled then return end\n        NexusState.fakeNameEnabled = true\n        applyFakeNameToAll()\n\n        local pg = LocalPlayer:FindFirstChild("PlayerGui")\n        if pg then\n            fakeNameConn = pg.DescendantAdded:Connect(function(desc)\n                if NexusState.fakeNameEnabled then\n                    task.wait(0.05)\n                    replaceTextInObject(desc)\n                end\n            end)\n        end\n\n        fakeNameThread = task.spawn(function()\n            while NexusState.fakeNameEnabled do\n                pcall(applyFakeNameToAll)\n                task.wait(1.5)\n            end\n        end)\n        NexusLib:Notify({ Title = "Streamer Mode", Message = "Fake name active: " .. tostring(NexusState.fakeName), Duration = 2 })\n    end\n\n    function NexusState.disableFakeName()\n        NexusState.fakeNameEnabled = false\n        if fakeNameConn then fakeNameConn:Disconnect(); fakeNameConn = nil end\n        if fakeNameThread then task.cancel(fakeNameThread); fakeNameThread = nil end\n        NexusLib:Notify({ Title = "Streamer Mode", Message = "Fake name disabled", Duration = 2 })\n    end\nend\n\n-- ============================================================\n-- Chong "cau tren troi": khi dang bay / vua teleport, player lo lung tren khong\n-- nen phao khong roi trung nuoc -> cast phi hoai. Raycast xuong kiem tra nuoc.\nfunction NexusState.isOverWater()\n    local ok, result = pcall(function()\n        local char = LocalPlayer.Character\n        local root = char and char:FindFirstChild("HumanoidRootPart")\n        if not root then return false end\n\n        local params = RaycastParams.new()\n        params.FilterType = Enum.RaycastFilterType.Exclude\n        params.FilterDescendantsInstances = { char }\n        params.IgnoreWater = false\n\n        local hit = Workspace:Raycast(root.Position, Vector3.new(0, -200, 0), params)\n        if not hit then return false end\n\n        if hit.Instance == Workspace.Terrain and hit.Material == Enum.Material.Water then\n            return true\n        end\n        local n = string.lower(hit.Instance.Name)\n        if string.find(n, "water") or string.find(n, "ocean") or string.find(n, "sea") then\n            return true\n        end\n        return false\n    end)\n    if not ok then return true end -- loi thi cho cast, khong chan oan\n    return result\nend\n\nfunction NexusState.canCastNow()\n    if NexusState.flying then return false end\n    -- Khi bat auto cast / farm boss / farm secret: tele len troi la chu y\n    -- (chong detect), vay isOverWater se false -> bo qua kiem tra nuoc,\n    -- chi chan khi dang fly thu cong.